// === Tab: mySketch ===
let simpleShader;
let newX = 0;
let newY = 0;
let oldX = 0;
let oldY = 0;
let img;
let flip = 0;
let pg;

function preload(){
  // Load the shader
  simpleShader = loadShader('https://openprocessing.org/sketch/1149671/files/basic.vert', 'basic.frag');

  // Load the image
  img = loadImage('https://openprocessing.org/sketch/1149671/files/thesisShow_web_bg.png');	
  //img = loadImage("https://openprocessing.org/sketch/1149671/files/mountain.jpg");

}

function setup() {
  // shaders require WEBGL mode to work
  createCanvas(1112, 834, WEBGL);
	pg = createGraphics(width, height);
	if (flip == 1){
	  pg.scale(1, -1);
	  pg.image(img, 0, -height, width, height);
  }else{
		pg.background(0);
    pg.image(img, 0, 0, width, height);
	}
  /*window.simulatedMouseX = width / 4;
	window.simulatedMouseY = height / 4;*/
}

function draw() {  
  if (frameCount%100 == 0){
    newX = random(width);
		newY = random(height);
	}
	if window.simulatedMouseX -=1;
	if window.simulatedMouseX +=1;
	if (newY > oldY) oldY-=1;
	if window.simulatedMouseY +=1;

  // shader() sets the active shader with our shader
  shader(simpleShader);

  const mx = map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, 30, 100);
  const my = map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, 30, 100);

  // Send the image to the shader
  simpleShader.setUniform("uTexture", pg);
  simpleShader.setUniform("uScale", [mx, my]);

  // rect gives us some geometry on the screen
  rect(0,0,width, height);

}

function keyPressed(){
    save('pix.jpg');
}

